/* Deliberately separate from static effects; no selectors activate without opt-in classes. */
@layer syn.effects {
  @keyframes syn-reading-progress {
    from { transform: scaleX(0); }
    to { transform: scaleX(1); }
  }
  /* All UI selectors are bounded by a Syntyr root. */
  :where(.syn-root, .syn-root *) {
    /* Opt-in, decorative scroll progress. Unsupported engines and reduced motion hide it. */
    &.syn-reading-progress { display: none; }
    @media (prefers-reduced-motion: no-preference) {
      @supports (animation-timeline: scroll(root block)) {
        &.syn-reading-progress {
          display: block;
          position: fixed;
          inset-block-start: 0;
          inset-inline-start: 0;
          inline-size: 100%;
          block-size: .2rem;
          background: var(--syn-accent);
          pointer-events: none;
          z-index: 50;
          transform-origin: left center;
          animation: syn-reading-progress linear both;
          animation-timeline: scroll(root block);
        }
      }
      /* Native details disclosure: no JavaScript, graceful fallback in engines
         without ::details-content or intrinsic size interpolation. */
      @supports (interpolate-size: allow-keywords) and selector(details::details-content) {
        &.syn-disclosure--transition {
          interpolate-size: allow-keywords;
        }
        &.syn-disclosure--transition::details-content {
          block-size: 0;
          overflow: clip;
          transition: block-size var(--syn-motion-duration) var(--syn-ease-out),
                      content-visibility var(--syn-motion-duration) allow-discrete;
        }
        &.syn-disclosure--transition[open]::details-content {
          block-size: auto;
        }
      }
      /* Native top-layer entry/exit animation without a JavaScript animation engine. */
      @supports (transition-behavior: allow-discrete) {
        &.syn-popover.syn-popover--transition {
          opacity: 0;
          transform: translateY(-.4rem);
          transition: opacity var(--syn-motion-duration) var(--syn-ease-out), transform var(--syn-motion-duration) var(--syn-ease-out), display var(--syn-motion-duration), overlay var(--syn-motion-duration);
          transition-behavior: allow-discrete;
        }
        &.syn-popover.syn-popover--transition:popover-open {
          opacity: 1;
          transform: translateY(0);
        }
        /* A dialog animates only when the host opts in to the motion module
           and the explicit transition class. Native focus and inertness stay intact. */
        &.syn-dialog.syn-dialog--transition {
          opacity: 0;
          transform: translateY(.4rem);
          transition: opacity var(--syn-motion-duration) var(--syn-ease-out), transform var(--syn-motion-duration) var(--syn-ease-out), display var(--syn-motion-duration), overlay var(--syn-motion-duration);
          transition-behavior: allow-discrete;
        }
        &.syn-dialog.syn-dialog--transition[open] {
          opacity: 1;
          transform: translateY(0);
        }
        @starting-style {
          &.syn-popover.syn-popover--transition:popover-open {
            opacity: 0;
            transform: translateY(-.4rem);
          }
          &.syn-dialog.syn-dialog--transition[open] {
            opacity: 0;
            transform: translateY(.4rem);
          }
        }
      }
    }
  }
}
